BEGIN;
SELECT pg_advisory_xact_lock(42042);
CREATE TEMP TABLE repair_expected AS SELECT '["{\"name\": \"西湖 游船\", \"tags\": [\"夜游\"], \"status\": \"open\", \"currency\": \"CNY\", \"location\": {\"lat\": 30.25, \"lon\": 120.15}, \"city_code\": \"HZ\", \"city_name\": \"杭州\", \"sync_deleted\": false, \"attraction_id\": \"p01\", \"sync_revision\": 3, \"ticket_price_fen\": 7000}", "{\"sync_deleted\": true, \"attraction_id\": \"p02\", \"sync_revision\": 2}", "{\"name\": \"西湖 园林\", \"tags\": [], \"status\": \"open\", \"currency\": \"CNY\", \"location\": {\"lat\": 31.32, \"lon\": 120.62}, \"city_code\": \"SZ\", \"city_name\": \"苏州\", \"sync_deleted\": false, \"attraction_id\": \"p03\", \"sync_revision\": 1, \"ticket_price_fen\": 3000}", "{\"name\": \"西湖 夜游\", \"tags\": [], \"status\": \"open\", \"currency\": \"CNY\", \"location\": {\"lat\": 30.252, \"lon\": 120.152}, \"city_code\": \"HZ\", \"city_name\": \"杭州\", \"sync_deleted\": false, \"attraction_id\": \"p04\", \"sync_revision\": 1, \"ticket_price_fen\": 4500}"]'::jsonb AS value;
-- Caller created repair_expected(value jsonb), an array of canonical JSON texts.
-- Keep the transaction lock until ALL affected IDs have emitted new revisions.
DO $$
BEGIN
  IF (SELECT jsonb_agg(f42.envelope(attraction_id)::text ORDER BY attraction_id)
      FROM f42.projection_clock)
     IS DISTINCT FROM (SELECT value FROM repair_expected) THEN
    RAISE EXCEPTION 'stale repair plan: current source differs; audit again';
  END IF;
END $$;

SELECT f42.emit('p01');
SELECT f42.emit('p02');
SELECT f42.emit('p04');
COMMIT;
